<script setup>
import {ref,defineAsyncComponent,onMounted,onBeforeUnmount} from 'vue'
import Icon from '../Icon.vue'
import {previewMode} from '../preview/mode'
import {currentSession} from '../lib/api'
import {requestPasswordReset,signIn,signInWithGoogle,updatePassword} from '../lib/supabase'
const Preview=previewMode?defineAsyncComponent(()=>import('../preview/PreviewShell.vue')):null
const Campus=defineAsyncComponent(()=>import('./SupabaseCampus.vue'))
const Signup=defineAsyncComponent(()=>import('./RegistrationFlow.vue'))
const localPreviewAvailable=import.meta.env.DEV&&['localhost','127.0.0.1','[::1]'].includes(location.hostname)
const session=ref(null),error=ref(''),busy=ref(true),selected=ref('Student'),signup=ref(false),dark=ref(false)
const email=ref(''),password=ref(''),notice=ref(''),showPassword=ref(false)
const recoverySession=ref(null),newPassword=ref('')
const roles=[{name:'Student',icon:'GraduationCap',text:'Learn, explore and grow.'},{name:'Teacher',icon:'BookOpen',text:'Individual teacher or institute.'}]
async function accept(data){session.value=data;password.value=''}
async function login(){
  error.value='';notice.value=''
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())){error.value='Enter a valid email address.';return}
  if(!password.value){error.value='Enter your password.';return}
  busy.value=true
  try{await accept(await signIn(email.value.trim(),password.value))}catch(e){error.value=e.message}finally{busy.value=false}
}
async function google(){error.value='';try{await signInWithGoogle()}catch(e){error.value=e.message}}
async function reset(){error.value='';notice.value='';try{if(!email.value)throw Error('Enter your email first.');await requestPasswordReset(email.value);notice.value='Password reset email sent.'}catch(e){error.value=e.message}}
async function savePassword(){busy.value=true;error.value='';try{const result=await updatePassword(newPassword.value);session.value=null;recoverySession.value=null;newPassword.value='';notice.value=result.message;history.replaceState({},'',location.pathname)}catch(e){error.value=e.message}finally{busy.value=false}}
async function connect(){busy.value=true;error.value='';try{session.value=await currentSession()}catch(e){session.value=null;if(e.status!==401)error.value=e.message}finally{busy.value=false}}
async function authenticated(value){session.value=value;signup.value=false}
function logout(){session.value=null;recoverySession.value=null}
function expired(){logout();error.value='Your session expired. Please sign in again.'}
onMounted(async()=>{if(previewMode)return;window.addEventListener('sisu-session-expired',expired);const params=new URLSearchParams(location.search);await connect();if(params.get('recovery')==='1'&&session.value)recoverySession.value=true;if(params.has('auth_error'))error.value='The sign-in link could not be completed. Request a new link and open it in the same browser.';if(params.has('auth_error')||params.has('recovery'))history.replaceState({},'',location.pathname)})
onBeforeUnmount(()=>window.removeEventListener('sisu-session-expired',expired))
</script>
<template>
  <Preview v-if="previewMode"/>
  <main v-else-if="recoverySession" class="entry-onboarding"><h1>Choose a new password</h1><p v-if="error" class="error">{{error}}</p><form @submit.prevent="savePassword"><label>New password<input v-model="newPassword" type="password" autocomplete="new-password" minlength="8" maxlength="72" required></label><button class="button primary" :disabled="busy">Update password</button></form></main>
  <Campus v-else-if="session" :session="session" @session="session=$event" @logout="logout"/>
  <Signup v-else-if="signup" @back="signup=false" @authenticated="authenticated"/>
  <main v-else class="sisu-entry" :class="{'entry-dark':dark}">
    <header><a href="#" class="entry-brand">sisu<span>✦</span></a><div><span class="entry-note">A little space. A world of possibility.</span><button class="entry-icon" @click="dark=!dark" :aria-label="dark?'Light mode':'Dark mode'"><Icon :name="dark?'Sun':'Moon'"/></button></div></header>
    <div class="entry-layout"><section class="entry-story"><span class="entry-kicker">YOUR NEXT CHAPTER STARTS HERE</span><h1>Big dreams.<br>Little steps.<br><em>Your space.</em></h1><p>A calm home for learning, teaching and all the wonderful things you’ll become.</p><div class="entry-garden" aria-hidden="true"><span class="entry-orbit"></span><div class="entry-book"><Icon name="BookOpen" :size="75"/><span>Keep growing.</span></div><span class="garden-spark">✧</span><span class="garden-leaf">❧</span><span class="garden-dot"></span></div><footer><span>✦ A place to belong</span><span>Made for curious minds</span></footer></section>
    <section class="entry-card"><span class="entry-kicker">COME ON IN</span><h2>It’s good to see you.</h2><p>Choose your space to get started.</p><div class="entry-roles"><button v-for="r in roles" :key="r.name" @click="selected=r.name" :class="{selected:selected===r.name}" :aria-pressed="selected===r.name"><span><Icon :name="r.icon" :size="21"/></span><div><strong>{{r.name}}</strong><small>{{r.text}}</small></div><i>{{selected===r.name?'✓':'›'}}</i></button></div>
      <form class="entry-login" novalidate @submit.prevent="login"><label><span>Email address</span><input v-model="email" type="email" autocomplete="email" inputmode="email" placeholder="you@example.com"></label><label><span>Password</span><span class="entry-password"><input v-model="password" :type="showPassword?'text':'password'" autocomplete="current-password" placeholder="At least 8 characters"><button type="button" @click="showPassword=!showPassword" :aria-label="showPassword?'Hide password':'Show password'">{{showPassword?'Hide':'Show'}}</button></span></label><div class="entry-login-meta"><button type="button" class="entry-forgot" @click="reset">Forgot password?</button></div><button type="submit" class="entry-primary" :disabled="busy">{{busy?'Checking…':'Sign in securely'}}</button></form><button v-if="selected==='Student'" class="entry-secondary entry-google" @click="google">G · Continue with Google</button><p v-if="notice" class="entry-notice" role="status">{{notice}}</p><div v-if="error" class="entry-status entry-error" role="alert"><span class="status-dot"></span><div><strong>We couldn’t sign you in</strong><p>{{error}}</p></div></div><p class="entry-secure"><Icon name="ShieldCheck" :size="15"/>Supabase authentication · Secure application session</p><div class="entry-divider"><span>NEW TO SISU?</span></div><button class="entry-secondary" @click="signup=true">Create your account <Icon name="Plus" :size="16"/></button><p class="entry-subtle">Students can start after verification. Teacher and institute roles require approval.</p>
      <a v-if="localPreviewAvailable" class="entry-primary" style="margin-top:20px" href="/?preview=1">Explore the full platform preview →</a>
    </section></div><footer class="entry-bottom">Your classes. Your people. Your own pace.<span>Secure access · No sample accounts</span></footer>
  </main>
</template>
<style>
.sisu-entry{--entry-bg:#f6f2fc;--entry-card:#fffcff;--entry-ink:#3b3050;--entry-muted:#7b708b;--entry-border:#e5dcef;min-height:100vh;background:var(--entry-bg);color:var(--entry-ink);padding:34px max(28px,6vw);font-family:Inter,system-ui,sans-serif}.sisu-entry.entry-dark{--entry-bg:#201a2d;--entry-card:#2c243b;--entry-ink:#eee5fc;--entry-muted:#b3a5c5;--entry-border:#453854}.sisu-entry header,.sisu-entry header>div,.entry-bottom,.entry-story footer{display:flex;align-items:center;justify-content:space-between;gap:25px}.entry-brand{font-size:39px;font-weight:800;letter-spacing:-3px;color:inherit;text-decoration:none}.entry-brand span{color:#a28ac6;font-size:22px;margin-left:8px}.entry-note{font-size:12px;color:var(--entry-muted)}.entry-icon{background:var(--entry-card);border:1px solid var(--entry-border);border-radius:50%;padding:12px;color:inherit;cursor:pointer}.entry-layout{display:grid;grid-template-columns:1.1fr 1fr;gap:9%;max-width:1240px;margin:70px auto 50px;align-items:center}.entry-kicker{font-size:10px;letter-spacing:2.7px;font-weight:600;color:var(--entry-muted)}.entry-story h1{font-size:clamp(44px,5vw,74px);line-height:1.12;letter-spacing:-3px;margin:27px 0}.entry-story h1 em{color:#9470bd;font-style:normal}.entry-story>p{max-width:365px;color:var(--entry-muted);font-size:15px;line-height:1.9}.entry-garden{position:relative;height:210px;margin:20px 0;display:grid;place-items:center;max-width:370px}.entry-book{width:150px;height:166px;background:linear-gradient(150deg,#eee0ff,#bc9ce1);border:5px solid #fff8;border-radius:26px 38px 28px 12px;box-shadow:15px 16px 0 #a38bb43a,20px 24px 35px #8c73a51c;transform:rotate(-10deg);display:flex;align-items:center;justify-content:center;gap:13px;flex-direction:column;color:#755398}.entry-book span{font-size:12px;font-weight:600}.entry-orbit{position:absolute;width:310px;height:145px;border:1px solid #bdaaca60;border-radius:50%;transform:rotate(-20deg)}.garden-spark{position:absolute;right:25px;top:15px;color:#a082c5;font-size:62px}.garden-leaf{position:absolute;left:0;bottom:0;color:#88a797;font-size:120px;transform:rotate(-30deg)}.garden-dot{width:22px;height:22px;background:#e7c59d;border-radius:50%;position:absolute;bottom:30px;right:38px}.entry-story footer{justify-content:flex-start;font-size:11px;color:var(--entry-muted)}.entry-card{min-width:0;padding:38px;border:1px solid var(--entry-border);border-radius:30px;background:var(--entry-card);box-shadow:0 25px 70px #6a43860b}.entry-card *{box-sizing:border-box}.entry-card h2{font-size:30px;letter-spacing:-1px;margin:14px 0}.entry-card>p{font-size:13px;color:var(--entry-muted);line-height:1.7}.entry-roles{display:grid;gap:10px;margin:26px 0}.entry-roles button{display:flex;align-items:center;gap:14px;width:100%;padding:15px;border:1px solid var(--entry-border);border-radius:15px;background:transparent;color:inherit;cursor:pointer;text-align:left}.entry-roles button.selected{background:#a98ac01a;border-color:#a98ac0}.entry-roles button>span{background:#a98ac019;padding:10px;border-radius:12px;color:#9674b4}.entry-roles button div{display:grid;gap:5px;flex:1}.entry-roles strong{font-size:13px}.entry-roles small{font-size:11px;color:var(--entry-muted)}.entry-roles i{font-style:normal;color:#9874b8}.entry-login{display:grid;gap:16px;margin-top:24px}.entry-login label{display:grid;gap:8px;min-width:0;color:var(--entry-muted);font-size:11px;font-weight:600}.entry-login input{display:block;width:100%;min-width:0;height:48px;padding:0 14px;border:1px solid var(--entry-border);border-radius:12px;outline:none;background:var(--entry-bg);color:var(--entry-ink);font:inherit;font-size:14px}.entry-login input:focus{border-color:#9674b4;box-shadow:0 0 0 3px #9674b422}.entry-password{position:relative;display:block}.entry-password input{padding-right:62px}.entry-password button{position:absolute;right:7px;top:7px;height:34px;padding:0 10px;border:0;border-radius:8px;background:transparent;color:#8b6fa5;font-size:11px;cursor:pointer}.entry-login-meta{display:flex;justify-content:flex-end;margin-top:-6px}.entry-forgot,.text-button{padding:0;border:0;background:transparent;color:#8667a4;font-size:11px;text-decoration:underline;cursor:pointer}.entry-primary,.entry-secondary{display:flex;align-items:center;justify-content:center;gap:15px;border:0;border-radius:13px;padding:16px;font-size:13px;font-weight:600;width:100%;text-decoration:none;cursor:pointer}.entry-primary{background:#8c6ab0;color:#fff;box-shadow:0 7px 16px #8c6ab020}.entry-primary:disabled{cursor:wait;opacity:.65}.entry-secondary{border:1px solid var(--entry-border);color:inherit;background:transparent}.entry-google{margin-top:12px}.entry-notice{padding:12px;border-radius:11px;background:#e8f5ee;color:#376451!important}.entry-secure{display:flex;align-items:center;justify-content:center;gap:7px;font-size:10px!important;margin:13px 0}.entry-divider{border-top:1px solid var(--entry-border);text-align:center;margin:26px 0 20px;height:0}.entry-divider span{position:relative;top:-8px;padding:0 14px;background:var(--entry-card);font-size:9px;letter-spacing:1px;color:var(--entry-muted)}.entry-subtle{font-size:10px!important;text-align:center;margin:14px 8px}.entry-status{margin-top:15px;padding:13px;display:flex;gap:10px;border:1px solid var(--entry-border);border-radius:12px;font-size:11px;color:var(--entry-muted);line-height:1.6}.entry-status p{margin:4px 0}.entry-error{border-color:#e7c5ce;background:#fff4f6;color:#7e3346}.entry-error .status-dot{background:#b74b65}.status-dot{background:#c7a478;width:7px;height:7px;border-radius:50%;margin-top:5px;flex-shrink:0}.entry-bottom{font-size:11px;color:var(--entry-muted);max-width:1240px;margin:auto}.entry-onboarding{max-width:780px;margin:70px auto;padding:25px}.entry-onboarding>a{margin-right:20px}@media(max-width:850px){.entry-layout{gap:35px;margin-top:40px}.entry-card{padding:25px}.entry-story h1{font-size:46px}.entry-note{display:none}.entry-garden{transform:scale(.85);transform-origin:left}}@media(max-width:640px){.sisu-entry{padding:22px 18px}.entry-layout{grid-template-columns:1fr;margin-top:35px}.entry-story h1{font-size:44px}.entry-story>p{font-size:13px}.entry-garden,.entry-story footer{display:none}.entry-bottom{flex-direction:column;gap:10px;text-align:center}.entry-card{padding:22px}.entry-card h2{font-size:26px}}
</style>
<style scoped>
.entry-provider-login{display:grid;gap:12px;margin:6px 0 2px}.entry-provider-login label{display:grid;gap:7px;font-size:11px;color:var(--entry-muted)}.entry-provider-login input{width:100%;padding:12px 13px;border:1px solid var(--entry-border);border-radius:11px;background:var(--entry-card);color:var(--entry-ink);font:inherit}.entry-provider-login .entry-primary{border:0}
</style>
